import java.io.*;
import java.util.*;

public class Main {
    // Blocos (slots): o carro colocado em um slot com "c" carros atrás dele na mesma
    // fila contribui T * F_j * c para a soma total das esperas.
    // Cada mecânico j oferece os slots c = 0, 1, 2, ... com custo por unidade: F_j * c.
    // Para um conjunto de slots fixo, o ótimo é parear os maiores T com os menores custos
    // (desigualdade do rearranjo). A escolha ótima dos slots é: os N menores custos
    // globais F_j * c (a estrutura de "prefixo" por mecânico é satisfeita automaticamente,
    // pois dentro de um mesmo mecânico os custos crescem estritamente com c),
    // o que equivale a um merge das M listas (0, F_j, 2*F_j, ...) via min-heap.

    private static final int SHIFT = 17;               // M <= 1e5 < 2^17
    private static final int MASK = (1 << SHIFT) - 1;  // custo <= 1e4*1e5 = 1e9 < 2^30

    private static long[] heap;
    private static int size;

    public static void main(String[] args) throws IOException {
        StreamTokenizer tk = new StreamTokenizer(new BufferedInputStream(System.in, 1 << 16));
        tk.nextToken();
        int n = (int) tk.nval;
        tk.nextToken();
        int m = (int) tk.nval;

        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            tk.nextToken();
            t[i] = (int) tk.nval;
        }
        int[] f = new int[m];
        for (int j = 0; j < m; j++) {
            tk.nextToken();
            f[j] = (int) tk.nval;
        }

        // Se há mecânicos suficientes, cada carro é o primeiro da sua fila: espera 0.
        if (m >= n) {
            System.out.println(0);
            return;
        }

        // Min-heap de chaves (custo << SHIFT | índiceDoMecanico), iniciando com os M slots de custo 0.
        heap = new long[m + 1];
        size = 0;
        for (int j = 0; j < m; j++) push(j); // custo 0, mecânico j

        long[] costs = new long[n];
        for (int i = 0; i < n; i++) {
            long key = pop();
            int j = (int) (key & MASK);
            long c = key >>> SHIFT;
            costs[i] = c;
            // próximo slot do mesmo mecânico: custo (c + F_j)
            push(((c + f[j]) << SHIFT) | j);
        }

        Arrays.sort(costs);   // custos crescentes
        Arrays.sort(t);       // T crescente; usaremos em ordem decrescente

        long total = 0;
        // Maior carro -> menor custo (posição mais atrás / mecânico mais rápido)
        for (int i = 0; i < n; i++) {
            total += (long) t[n - 1 - i] * costs[i];
        }
        System.out.println(total);
    }

    private static void push(long key) {
        int i = ++size;
        heap[i] = key;
        while (i > 1) {
            int p = i >> 1;
            if (heap[p] <= heap[i]) break;
            long tmp = heap[i]; heap[i] = heap[p]; heap[p] = tmp;
            i = p;
        }
    }

    private static long pop() {
        long r = heap[1];
        heap[1] = heap[size--];
        int i = 1;
        while (true) {
            int l = i << 1;
            int s = i;
            if (l <= size && heap[l] < heap[s]) s = l;
            if (l + 1 <= size && heap[l + 1] < heap[s]) s = l + 1;
            if (s == i) break;
            long tmp = heap[i]; heap[i] = heap[s]; heap[s] = tmp;
            i = s;
        }
        return r;
    }
}
